-- ใส่เลขใบกันเหลื่อมให้สัญญาเภสัช (APF) ที่นำเข้าไปแล้วโดยไม่มีเลขใบกัน (ตามคอลัมน์ "เลขที่กันเหลื่อมปี" ในไฟล์ Excel เภสัช)
-- ใส่เฉพาะแถวที่ c_overlap ว่างอยู่ ไม่ทับค่าเดิม | ไม่มี COMMIT: เอา -- หน้า UPDATE ออกเพื่อรันจริง
USE NMU_ERP;
SET NOCOUNT ON;
CREATE TABLE #ov(c_contract_code nvarchar(100) COLLATE DATABASE_DEFAULT, c_overlap nvarchar(100) COLLATE DATABASE_DEFAULT);

SELECT COUNT(*) AS n_will_update FROM NMU_ERP.dbo.sp_tor_period_bill g JOIN #ov o ON o.c_contract_code=g.c_contract_code
 WHERE g.c_ap_dept_type=N'APF' AND g.i_enabled=1 AND ISNULL(g.c_overlap,'')='';
SELECT COUNT(*) AS n_overlap_not_in_budget FROM #ov o WHERE NOT EXISTS (SELECT 1 FROM NMU_EIS.dbo.vw_bg_budget_overlap v WHERE v.c_code_ref COLLATE DATABASE_DEFAULT=o.c_overlap AND v.dc_cost_id=50);
-- UPDATE g SET g.c_overlap=o.c_overlap,
--   g.i_budget_year_overlap=(SELECT TOP 1 v.i_year FROM NMU_EIS.dbo.vw_bg_budget_overlap v WHERE v.c_code_ref COLLATE DATABASE_DEFAULT=o.c_overlap AND v.dc_cost_id=50 ORDER BY v.i_year DESC)
-- FROM NMU_ERP.dbo.sp_tor_period_bill g JOIN #ov o ON o.c_contract_code=g.c_contract_code
-- WHERE g.c_ap_dept_type=N'APF' AND g.i_enabled=1 AND ISNULL(g.c_overlap,'')='';
DROP TABLE #ov;
